js:
var sc = root.querySelector('.scp-strata-hero-scroll');
if (!sc) { return; }
function q(s){ return root.querySelector(s); }
var layers = [
  [q('.scp-strata-hero-sky'), 0.06],
  [q('.scp-strata-hero-sun'), 0.10],
  [q('.scp-strata-hero-far'), 0.18],
  [q('.scp-strata-hero-fog'), 0.26],
  [q('.scp-strata-hero-mid'), 0.34],
  [q('.scp-strata-hero-near'), 0.62],
  [q('.scp-strata-hero-title'), 0.88]
];
var title = q('.scp-strata-hero-title');
var cue = q('.scp-strata-hero-cue');
var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
var queued = false;

function frame(){
  if (!root.isConnected) { return; }
  queued = false;
  if (mq && mq.matches) { return; }
  var y = sc.scrollTop;
  for (var i = 0; i < layers.length; i++) {
    var el = layers[i][0];
    if (el) { el.style.transform = 'translate3d(0,' + (-y * layers[i][1]).toFixed(2) + 'px,0)'; }
  }
  if (title) { title.style.opacity = String(Math.max(0, 1 - y / 110)); }
  if (cue) { cue.style.opacity = String(Math.max(0, 1 - y / 36)); }
}

function onScroll(){
  if (!queued) { queued = true; requestAnimationFrame(frame); }
}
sc.addEventListener('scroll', onScroll, { passive: true });
requestAnimationFrame(frame);

