}

js:
var sc = root.querySelector('.scp-plate-gallery-scroll');
if (!sc) { return; }
var cards = Array.prototype.slice.call(root.querySelectorAll('.scp-plate-gallery-card'));
var count = root.querySelector('.scp-plate-gallery-count');
var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
var queued = false;

function frame(){
  if (!root.isConnected) { return; }
  queued = false;
  if (mq && mq.matches) { return; }
  var span = sc.clientHeight || 1;
  var mid = sc.scrollTop + span / 2;
  for (var i = 0; i < cards.length; i++) {
    var plate = cards[i].querySelector('.scp-plate-gallery-plate');
    if (!plate) { continue; }
    var t = ((cards[i].offsetTop + cards[i].offsetHeight / 2) - mid) / span;
    if (t > 1.5) { t = 1.5; }
    if (t < -1.5) { t = -1.5; }
    plate.style.transform = 'translate3d(0,' + (t * 24).toFixed(2) + 'px,0)';
  }
}

function onScroll(){
  if (!queued) { queued = true; requestAnimationFrame(frame); }
}
sc.addEventListener('scroll', onScroll, { passive: true });
requestAnimationFrame(frame);

function sync(){
  var n = root.querySelectorAll('.scp-plate-gallery-save[aria-pressed="true"]').length;
  if (count) { count.textContent = n ? n + ' in set' : cards.length + ' plates'; }
}

root.addEventListener('click', function (e) {
  var b = e.target && e.target.closest ? e.target.closest('.scp-plate-gallery-save') : null;
  if (!b || !root.contains(b)) { return; }
  var on = b.getAttribute('aria-pressed') === 'true';
  b.setAttribute('aria-pressed', on ? 'false' : 'true');
  b.textContent = on ? 'Save' : 'Saved';
  sync();
});

css:
