  .scp-ledger-drift-fill{animation-name:scp-ledger-drift-grow;animation-timing-function:linear;animation-fill-mode:both;animation-duration:auto;animation-timeline:scroll(nearest block)}
}
@media (prefers-reduced-motion: reduce){
  .scp-ledger-drift-num,.scp-ledger-drift-grid{transform:none !important}
  .scp-ledger-drift-scroll{scroll-behavior:auto}
