js:
var sc = root.querySelector('.scp-ledger-drift-scroll');
if (!sc) { return; }
var num = root.querySelector('.scp-ledger-drift-num');
var grid = root.querySelector('.scp-ledger-drift-grid');
var fill = root.querySelector('.scp-ledger-drift-fill');
var now = root.querySelector('.scp-ledger-drift-now');
var when = root.querySelector('.scp-ledger-drift-when');
var col = root.querySelector('.scp-ledger-drift-col');
var rels = Array.prototype.slice.call(root.querySelectorAll('.scp-ledger-drift-rel'));
var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
var queued = false;
var current = null;

function mark(y, max){
  if (!rels.length) { return; }
  var base = col ? col.offsetTop : 0;
  var active = rels[0];
  for (var i = 0; i < rels.length; i++) {
    if (base + rels[i].offsetTop - 52 <= y) { active = rels[i]; }
  }
  if (y >= max - 4) { active = rels[rels.length - 1]; }
  if (active === current) { return; }
  current = active;
  for (var j = 0; j < rels.length; j++) {
    if (rels[j] === active) { rels[j].setAttribute('data-cur', '1'); }
    else { rels[j].removeAttribute('data-cur'); }
  }
  if (now) { now.textContent = active.getAttribute('data-v'); }
  if (when) { when.textContent = active.getAttribute('data-when'); }
}

function frame(){
  if (!root.isConnected) { return; }
  queued = false;
  var y = sc.scrollTop;
  var max = Math.max(1, sc.scrollHeight - sc.clientHeight);
  if (fill) { fill.style.transform = 'scaleX(' + Math.min(1, y / max).toFixed(4) + ')'; }
  mark(y, max);
  if (mq && mq.matches) { return; }
  if (num) { num.style.transform = 'translate3d(0,' + (-y * 0.16).toFixed(2) + 'px,0)'; }
  if (grid) { grid.style.transform = 'translate3d(0,' + (-y * 0.44).toFixed(2) + 'px,0)'; }
}

function onScroll(){
  if (!queued) { queued = true; requestAnimationFrame(frame); }
}
sc.addEventListener('scroll', onScroll, { passive: true });
requestAnimationFrame(frame);

