var layers = Array.prototype.slice.call(root.querySelectorAll('.scp-pointer-depth-l')).map(function (el) {
  return {
    el: el,
    dx: parseFloat(el.getAttribute('data-dx')) || 0,
    dy: parseFloat(el.getAttribute('data-dy')) || 0,
    sy: parseFloat(el.getAttribute('data-sy')) || 0
