  for (var i = 0; i < layers.length; i++) {
    var L = layers[i];
    L.el.style.transform = 'translate3d(' + (cx * L.dx).toFixed(2) + 'px,' + (cy * L.dy - sy * L.sy).toFixed(2) + 'px,0)';
    if (L.sy >= 0.5) { L.el.style.opacity = fade.toFixed(3); }
  }
}

function loop(){
  if (!root.isConnected) { running = false; return; }
  cx += (tx - cx) * 0.14;
  cy += (ty - cy) * 0.14;
  render();
  if (Math.abs(tx - cx) > 0.002 || Math.abs(ty - cy) > 0.002) {
    requestAnimationFrame(loop);
  } else {
    cx = tx; cy = ty; render(); running = false;
  }
}

function kick(){
  if (mq && mq.matches) { return; }
  if (!running) { running = true; requestAnimationFrame(loop); }
}

root.addEventListener('pointermove', function (e) {
  var r = root.getBoundingClientRect();
  if (!r.width || !r.height) { return; }
  tx = (e.clientX - r.left) / r.width * 2 - 1;
  ty = (e.clientY - r.top) / r.height * 2 - 1;
  kick();
});

root.addEventListener('pointerleave', function () {
  tx = 0; ty = 0; kick();
});

sc.addEventListener('scroll', function () {
  sy = sc.scrollTop;
  kick();
}, { passive: true });

kick();

