js:
var sc = root.querySelector('.scp-rate-inspector-scroll');
if (!sc) { return; }
var PRESETS = { subtle: [0.12, 0.30, 0.60], standard: [0.22, 0.55, 1.00], extreme: [0.40, 0.85, 1.60] };
var keys = ['bg', 'mid', 'fg'];
var cols = keys.map(function (k) {
  var col = root.querySelector('.scp-rate-inspector-col[data-layer="' + k + '"]');
  return {
    strip: col ? col.querySelector('.scp-rate-inspector-strip') : null,
    lab: col ? col.querySelector('.scp-rate-inspector-lab b') : null,
    period: 0
  };
});
var code = root.querySelector('.scp-rate-inspector-code');
var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
var rates = PRESETS.standard;
var queued = false;

function frame(){
  if (!root.isConnected) { return; }
  queued = false;
  var y = sc.scrollTop;
  var parts = ['scrollTop ' + Math.round(y)];
  for (var i = 0; i < cols.length; i++) {
    var raw = y * rates[i];
    parts.push(keys[i] + ' ' + Math.round(-raw));
    var strip = cols[i].strip;
    if (!strip || (mq && mq.matches)) { continue; }
    var period = cols[i].period;
    if (!period) {
      var chips = strip.children;
      period = chips.length > 4 ? chips[4].offsetTop - chips[0].offsetTop : 0;
      cols[i].period = period;
    }
    var off = period > 0 ? -(raw % period) : 0;
    strip.style.transform = 'translate3d(0,' + off.toFixed(2) + 'px,0)';
  }
  if (code) { code.textContent = parts.join('  ·  '); }
}

function onScroll(){
  if (!queued) { queued = true; requestAnimationFrame(frame); }
}
sc.addEventListener('scroll', onScroll, { passive: true });
requestAnimationFrame(frame);

root.addEventListener('click', function (e) {
  var b = e.target && e.target.closest ? e.target.closest('.scp-rate-inspector-p') : null;
  if (!b || !root.contains(b)) { return; }
  var name = b.getAttribute('data-p');
  if (!PRESETS[name]) { return; }
  rates = PRESETS[name];
  var all = root.querySelectorAll('.scp-rate-inspector-p');
  for (var i = 0; i < all.length; i++) { all[i].setAttribute('aria-pressed', all[i] === b ? 'true' : 'false'); }
  for (var j = 0; j < cols.length; j++) {
    if (cols[j].lab) { cols[j].lab.textContent = rates[j].toFixed(2); }
  }
  requestAnimationFrame(frame);
});

