var sc = root.querySelector('.scp-railcar-banner-scroll');
if (!sc) { return; }
function q(n){ return root.querySelector('.scp-railcar-banner-' + n); }
var sun = q('sun');
var beds = [[q('hills'),0.14],[q('hedge'),0.30],[q('poles'),0.55],[q('ties'),1.15]];
var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
var queued = false;
function frame(){
  if (!root.isConnected) { return; }
  queued = false;
  var x = (mq && mq.matches) ? 0 : sc.scrollLeft;
  for (var i = 0; i < beds.length; i++) {
    if (beds[i][0]) { beds[i][0].style.backgroundPositionX = (-x * beds[i][1]).toFixed(1) + 'px'; }
  }
  if (sun) { sun.style.transform = 'translate3d(' + (-x * 0.05).toFixed(2) + 'px,0,0)'; }
}
sc.addEventListener('scroll', function(){ if (!queued) { queued = true; requestAnimationFrame(frame); } }, { passive: true });
requestAnimationFrame(frame);

