js:
var sc = root.querySelector('.scp-holo-shelf-scroll');
if (!sc) { return; }
var cards = root.querySelectorAll('.scp-holo-shelf-card');
var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
function reduced(){ return !!(mq && mq.matches); }
function setVar(card, n, v){ card.style.setProperty('--scp-holo-shelf-' + n, v.toFixed(3)); }
var queued = false;
function frame(){
  if (!root.isConnected) { return; }
  queued = false;
  var cr = sc.getBoundingClientRect();
  var mid = cr.top + cr.height / 2;
  for (var i = 0; i < cards.length; i++) {
    if (reduced()) { setVar(cards[i], 'sy', 0); continue; }
    var r = cards[i].getBoundingClientRect();
    var raw = ((r.top + r.height / 2) - mid) / (cr.height / 2);
    setVar(cards[i], 'sy', raw > 1 ? 1 : (raw < -1 ? -1 : raw));
  }
}
sc.addEventListener('scroll', function(){ if (!queued) { queued = true; requestAnimationFrame(frame); } }, { passive: true });
requestAnimationFrame(frame);
for (var c = 0; c < cards.length; c++) {
  (function(card){
    card.addEventListener('pointermove', function(ev){
      if (reduced()) { return; }
      var r = card.getBoundingClientRect();
      setVar(card, 'px', ((ev.clientX - r.left) / r.width) * 2 - 1);
      setVar(card, 'py', ((ev.clientY - r.top) / r.height) * 2 - 1);
    });
    card.addEventListener('pointerleave', function(){ setVar(card, 'px', 0); setVar(card, 'py', 0); });
    var btn = card.querySelector('.scp-holo-shelf-btn');
    if (btn) {
      btn.addEventListener('focus', function(){ if (!reduced()) { setVar(card, 'px', 0.4); setVar(card, 'py', -0.35); } });
      btn.addEventListener('blur', function(){ setVar(card, 'px', 0); setVar(card, 'py', 0); });
    }
  })(cards[c]);
}

