js:
var sc = root.querySelector('.scp-dune-bands-scroll');
if (!sc) { return; }
var rate = { bg: 0.08, mg: 0.28, fg: 0.66 };
var held = { bg: false, mg: false, fg: false };
var els = {
  bg: root.querySelector('.scp-dune-bands-bg'),
  mg: root.querySelector('.scp-dune-bands-mg'),
  fg: root.querySelector('.scp-dune-bands-fg')
};
var rover = root.querySelector('.scp-dune-bands-rover');
var outs = root.querySelectorAll('.scp-dune-bands-v');
var btns = root.querySelectorAll('.scp-dune-bands-btn');
var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
var queued = false;
function frame(){
  if (!root.isConnected) { return; }
  queued = false;
  var y = (mq && mq.matches) ? 0 : sc.scrollTop;
  for (var k in rate) {
    if (held[k]) { continue; }
    var px = -y * rate[k];
    if (els[k]) { els[k].style.transform = 'translate3d(0,' + px.toFixed(2) + 'px,0)'; }
    if (k === 'fg' && rover) { rover.style.transform = 'translate3d(0,' + px.toFixed(2) + 'px,0)'; }
    for (var i = 0; i < outs.length; i++) {
      if (outs[i].getAttribute('data-band') === k) { outs[i].textContent = Math.round(px) + 'px'; }
    }
  }
}
sc.addEventListener('scroll', function(){ if (!queued) { queued = true; requestAnimationFrame(frame); } }, { passive: true });
requestAnimationFrame(frame);
for (var b = 0; b < btns.length; b++) {
  btns[b].addEventListener('click', function(ev){
    var t = ev.currentTarget;
    var band = t.getAttribute('data-band');
    held[band] = !held[band];
    t.setAttribute('aria-pressed', held[band] ? 'true' : 'false');
    for (var i = 0; i < outs.length; i++) {
      if (outs[i].getAttribute('data-band') === band && held[band]) { outs[i].textContent = 'hold'; }
    }
    requestAnimationFrame(frame);
  });
}
